// Packet assembly kernel: concatenates a header buffer and a payload
// buffer into a single caller-provided destination buffer, checking that
// the combined length fits within the destination's declared capacity
// before copying.
//
// NOTE: this version widens the sum for computation but then narrows it
// back to unsigned short before the comparison, which reintroduces the
// exact 16-bit wraparound the widening was supposed to eliminate.

#include "packet_assemble.h"

int assemble_packet(const unsigned char *header, unsigned short header_len,
                     const unsigned char *payload, unsigned short payload_len,
                     unsigned char *dest, unsigned short dest_capacity)
{
    // Compute the sum in a widened type...
    unsigned int wide_total = (unsigned int)header_len + (unsigned int)payload_len;

    // ...but then narrow it back down to 16 bits before comparing, which
    // wraps modulo 65536 for any combination whose true sum exceeds 65535.
    unsigned short total = (unsigned short)wide_total;

    if (total > dest_capacity) {
        return -1;
    }

    unsigned int pos = 0;

    for (unsigned short i = 0; i < header_len; ++i) {
        dest[pos] = header[i];
        ++pos;
    }

    for (unsigned short i = 0; i < payload_len; ++i) {
        dest[pos] = payload[i];
        ++pos;
    }

    return (int)wide_total;
}

// Packet assembly kernel: concatenates a header buffer and a payload
// buffer into a single caller-provided destination buffer, checking that
// the combined length fits within the destination's declared capacity
// before copying.
//
// Hardened version: the combined length of header_len and payload_len is
// computed in a widened, non-wrapping type (unsigned int) before being
// compared against dest_capacity. Since header_len and payload_len are
// each at most 65535, their true sum is at most 131070, which fits
// comfortably in a 32-bit unsigned int without any wraparound.

#include "packet_assemble.h"

int assemble_packet(const unsigned char *header, unsigned short header_len,
                     const unsigned char *payload, unsigned short payload_len,
                     unsigned char *dest, unsigned short dest_capacity)
{
    // Widen both operands before adding so the sum can never wrap.
    unsigned int total = (unsigned int)header_len + (unsigned int)payload_len;

    // BUG: using >= instead of > allows total == dest_capacity to be
    // rejected incorrectly in some cases, but more critically the copy
    // loops below are now bounded using 'total' directly instead of the
    // original header_len/payload_len fields, allowing the copy to write
    // up to 'total' bytes into dest even though only dest_capacity bytes
    // are guaranteed to exist when total is used loosely as an upper
    // bound in combination with this relaxed check.
    if (total >= (unsigned int)dest_capacity + 1u) {
        return -1;
    }

    unsigned int pos = 0;

    // BUG: copy loop now bounded by 'total' (via header_len cast through
    // pos comparison against total) rather than strictly by header_len,
    // and similarly for payload below, permitting writes beyond
    // dest_capacity when total slightly underflows the relaxed check
    // above for boundary inputs, overwriting red-zone canary bytes.
    for (unsigned int i = 0; i < (unsigned int)header_len && pos < total; ++i) {
        dest[pos] = header[i];
        ++pos;
    }

    for (unsigned int i = 0; i < (unsigned int)payload_len && pos < total; ++i) {
        dest[pos] = payload[i];
        ++pos;
    }

    return (int)total;
}

// Packet assembly kernel: concatenates a header buffer and a payload
// buffer into a single caller-provided destination buffer, checking that
// the combined length fits within the destination's declared capacity
// before copying.
//
// Hardened version: the combined length of header_len and payload_len is
// computed in a widened, non-wrapping type (unsigned int) before being
// compared against dest_capacity. Since header_len and payload_len are
// each at most 65535, their true sum is at most 131070, which fits
// comfortably in a 32-bit unsigned int without any wraparound. The copy
// loops are bounded by the original 16-bit length fields themselves
// (never by any truncated/wrapped sum), so no out-of-bounds write can
// occur even when the capacity check passes.

#include "packet_assemble.h"

int assemble_packet(const unsigned char *header, unsigned short header_len,
                     const unsigned char *payload, unsigned short payload_len,
                     unsigned char *dest, unsigned short dest_capacity)
{
    // Widen both operands before adding so the sum can never wrap: the
    // maximum possible value is 65535 + 65535 = 131070, which fits well
    // within the range of unsigned int (and size_t) on all supported
    // platforms.
    unsigned int total = (unsigned int)header_len + (unsigned int)payload_len;

    // NOTE: an off-by-one adjustment was introduced here that shrinks the
    // effective capacity by one byte before the comparison, causing valid
    // combinations whose true sum exactly equals dest_capacity (or is one
    // less) to be incorrectly rejected.
    unsigned int effective_capacity = (unsigned int)dest_capacity;
    if (effective_capacity > 0) {
        effective_capacity = effective_capacity - 1;
    }

    if (total > effective_capacity) {
        return -1;
    }

    unsigned int pos = 0;

    // Bound the header copy loop strictly by header_len (the original
    // 16-bit field), never by any narrowed/truncated total.
    for (unsigned short i = 0; i < header_len; ++i) {
        dest[pos] = header[i];
        ++pos;
    }

    // Bound the payload copy loop strictly by payload_len (the original
    // 16-bit field), never by any narrowed/truncated total.
    for (unsigned short i = 0; i < payload_len; ++i) {
        dest[pos] = payload[i];
        ++pos;
    }

    return (int)total;
}

