    // NOTE: the position increment has been removed here, so every
    // payload byte overwrites the same destination slot instead of
    // advancing through dest.
    for (unsigned short i = 0; i < payload_len; ++i) {
        dest[pos] = payload[i];
    }

    return (int)total;
